CREATE FUNCTION public.biz_resolve_position(_position uuid,_sys uuid,_dep uuid,_team uuid,_at timestamptz DEFAULT now()) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$DECLARE p public.biz_positions;users_ uuid[];BEGIN
SELECT * INTO p FROM public.biz_positions WHERE id=_position;IF p.id IS NULL OR NOT p.active OR p.unit_kind='individual' THEN RETURN NULL;END IF;
SELECT array_agg(DISTINCT u) INTO users_ FROM (SELECT a.user_id u FROM public.biz_appointments a WHERE a.position_id=p.id AND a.status<>'cancelled' AND a.started_at<=_at AND (a.ended_at IS NULL OR a.ended_at>_at) AND ((a.scope_kind='system' AND a.system_id=_sys) OR (a.scope_kind='department' AND a.department_id=_dep) OR (a.scope_kind='team' AND a.team_id=_team)) UNION SELECT a.user_id FROM public.biz_management_assignments a WHERE a.position=p.code AND a.started_at<=_at AND (a.ended_at IS NULL OR a.ended_at>_at) AND ((p.unit_kind='system' AND a.system_id=_sys) OR (p.unit_kind='department' AND a.department_id=_dep) OR (p.unit_kind='team' AND a.team_id=_team))) q;
IF cardinality(users_)>1 THEN RAISE EXCEPTION 'Nhiều người cùng phụ trách chức vụ: %',p.name;END IF;RETURN users_[1];END $$;
CREATE FUNCTION public.biz_appointment_scope(_id uuid,_user uuid,_dept uuid,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.id=_id AND a.status<>'cancelled' AND a.started_at<=now() AND (a.ended_at IS NULL OR a.ended_at>now()) AND ((a.scope_kind='individual' AND a.user_id=_user) OR (a.scope_kind='department' AND a.department_id=_dept) OR (a.scope_kind='system' AND EXISTS(SELECT 1 FROM public.biz_department_system_history h WHERE h.department_id=_dept AND h.system_id=a.system_id AND h.started_at<=_at AND (h.ended_at IS NULL OR h.ended_at>_at))) OR (a.scope_kind='team' AND EXISTS(SELECT 1 FROM public.biz_team_members m JOIN public.biz_teams t ON t.id=m.team_id WHERE m.user_id=_user AND m.team_id=a.team_id AND t.department_id=_dept AND m.started_at<=_at AND (m.ended_at IS NULL OR m.ended_at>_at)))))$$;
CREATE FUNCTION public.biz_legacy_appointment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN PERFORM pg_advisory_xact_lock(hashtext('biz_org_structure'));IF EXISTS(SELECT 1 FROM public.biz_appointments a JOIN public.biz_positions p ON p.id=a.position_id WHERE p.code=NEW.position AND a.status<>'cancelled' AND CASE NEW.position WHEN 'director' THEN NEW.system_id WHEN 'department_head' THEN NEW.department_id ELSE NEW.team_id END=CASE a.scope_kind WHEN 'system' THEN a.system_id WHEN 'department' THEN a.department_id ELSE a.team_id END AND tstzrange(a.started_at,a.ended_at,'[)') && tstzrange(NEW.started_at,NEW.ended_at,'[)')) THEN RAISE EXCEPTION 'Trùng thời gian với quyết định bổ nhiệm chức vụ.';END IF;RETURN NEW;END $$;
CREATE TRIGGER biz_legacy_appointment_guard BEFORE INSERT OR UPDATE ON public.biz_management_assignments FOR EACH ROW EXECUTE FUNCTION public.biz_legacy_appointment_guard();
DO $$DECLARE def text;BEGIN
SELECT pg_get_functiondef('public.biz_scope_ok(uuid,uuid,uuid,timestamptz)'::regprocedure) INTO def;
def:=replace(def,'OR EXISTS(', 'OR EXISTS(');
def:=replace(def,'OR EXISTS('||chr(10)||' SELECT 1 FROM public.biz_management_assignments', 'OR EXISTS(SELECT 1 FROM public.biz_appointments a WHERE a.user_id=_actor AND public.biz_appointment_scope(a.id,_user,_dept,_at)) OR EXISTS('||chr(10)||' SELECT 1 FROM public.biz_management_assignments');
IF position('public.biz_appointment_scope' IN def)=0 THEN RAISE EXCEPTION 'Không khớp phạm vi tổ chức.';END IF;EXECUTE def;
SELECT pg_get_functiondef('public.biz_workflow_save(jsonb)'::regprocedure) INTO def;
IF position('NOT IN (''team_lead'',''department_head'',''director'',''user'')' IN def)=0 THEN RAISE EXCEPTION 'Không khớp định nghĩa luồng duyệt.';END IF;
def:=replace(def,'NOT IN (''team_lead'',''department_head'',''director'',''user'')','NOT IN (''team_lead'',''department_head'',''director'',''user'',''position'')');
def:=replace(def,'IF x->>''type''=''user'' AND NOT EXISTS','IF x->>''type''=''position'' AND NOT EXISTS(SELECT 1 FROM public.biz_positions WHERE id=nullif(x->>''position_id'','''')::uuid AND active AND unit_kind<>''individual'') THEN RAISE EXCEPTION ''Chức vụ xét duyệt không hợp lệ hoặc đã ngừng.'';END IF;IF x->>''type''=''user'' AND NOT EXISTS');EXECUTE def;
SELECT pg_get_functiondef('public.biz_approval_start(uuid,text,uuid,uuid,jsonb)'::regprocedure) INTO def;
IF position('ELSE SELECT user_id INTO approver FROM public.biz_management_assignments' IN def)=0 THEN RAISE EXCEPTION 'Không khớp xác định người duyệt.';END IF;
def:=replace(def,'IF x->>''type''=''user'' THEN approver:=nullif(x->>''user_id'','''')::uuid;','IF x->>''type''=''position'' THEN approver:=public.biz_resolve_position(nullif(x->>''position_id'','''')::uuid,sid,_dept,tid);IF approver=_owner AND coalesce((x->>''skip_if_submitter'')::boolean,false) THEN CONTINUE;END IF;ELSIF x->>''type''=''user'' THEN approver:=nullif(x->>''user_id'','''')::uuid;');
def:=replace(def,'WHERE ended_at IS NULL AND position=x->>''type''','WHERE started_at<=now() AND (ended_at IS NULL OR ended_at>now()) AND position=x->>''type''');
def:=replace(def,'resolved:=resolved||jsonb_build_array(x||jsonb_build_object(''user_id'',approver,''substitute_id'',sub));','resolved:=resolved||jsonb_build_array(x||jsonb_build_object(''user_id'',approver,''substitute_id'',sub,''position_snapshot'',CASE WHEN x->>''type''=''position'' THEN (SELECT to_jsonb(p) FROM public.biz_positions p WHERE p.id=(x->>''position_id'')::uuid) END));');EXECUTE def;END $$;
CREATE FUNCTION public.biz_workflow_preview(_data jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$DECLARE s public.biz_systems;d public.biz_departments;t record;x jsonb;u uuid;sub uuid;out_ jsonb:='[]';perm text:=CASE WHEN _data->>'kind'='goal_year' THEN 'biz.goal_approve' ELSE 'biz.report_approve' END;at_ timestamptz:=coalesce(nullif(_data->>'effective_from','')::timestamptz,now());BEGIN
IF NOT public.biz_workflow_manage() THEN RAISE EXCEPTION 'Không có quyền xem trước quy trình.';END IF;SELECT * INTO s FROM public.biz_systems WHERE id=nullif(_data->>'system_id','')::uuid;
FOR d IN SELECT * FROM public.biz_departments WHERE system_id=s.id AND active AND (nullif(_data->>'department_id','') IS NULL OR id=(_data->>'department_id')::uuid) LOOP
FOR t IN SELECT id,name FROM public.biz_teams WHERE department_id=d.id AND active UNION ALL SELECT NULL::uuid,'Chưa gán Nhóm' LOOP
FOR x IN SELECT * FROM jsonb_array_elements(coalesce(_data->'steps','[]')) LOOP
u:=NULL;sub:=nullif(x->>'substitute_id','')::uuid;IF x->>'type'='user' THEN u:=nullif(x->>'user_id','')::uuid;ELSE u:=public.biz_resolve_position(CASE WHEN x->>'type'='position' THEN nullif(x->>'position_id','')::uuid ELSE (SELECT id FROM public.biz_positions WHERE code=x->>'type') END,s.id,d.id,t.id,at_);END IF;
IF u IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND status='Đang hoạt động' AND private.sig_can(id,perm)) THEN u:=NULL;END IF;IF sub IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=sub AND status='Đang hoạt động' AND private.sig_can(id,perm)) THEN sub:=NULL;END IF;
out_:=out_||jsonb_build_array(jsonb_build_object('department',d.name,'team',t.name,'label',x->>'label','user_id',u,'substitute_id',sub,'missing',u IS NULL AND sub IS NULL));END LOOP;END LOOP;END LOOP;RETURN out_;END $$;
REVOKE ALL ON FUNCTION public.biz_resolve_position(uuid,uuid,uuid,uuid,timestamptz),public.biz_appointment_scope(uuid,uuid,uuid,timestamptz),public.biz_legacy_appointment_guard(),public.biz_workflow_preview(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_appointment_scope(uuid,uuid,uuid,timestamptz),public.biz_workflow_preview(jsonb) TO authenticated;